const emails = $input.all();
const VIP_EMAILS = ['julie.a.siegel84@gmail.com', 'jabentley9@gmail.com'];

const categorized = {
  VIP: [],
  Business: [],
  Personal: [],
  Other: []
};

emails.forEach(item => {
  const email = item.json;
  const from = email.from.value || email.from;
  const subject = email.subject || '(No Subject)';

  const entry = `- *${from}*: ${subject}`;

  if (VIP_EMAILS.some(vip => from.toLowerCase().includes(vip))) {
    categorized.VIP.push(entry);
  } else if (from.toLowerCase().includes('dainbentley.com') || subject.toLowerCase().includes('notary')) {
    categorized.Business.push(entry);
  } else {
    categorized.Personal.push(entry);
  }
});

let message = "📩 *Email Digest*\n\n";

if (categorized.VIP.length > 0) {
  message += "🔴 *VIP (Julie/Jen)*\n" + categorized.VIP.join('\n') + "\n\n";
}

if (categorized.Business.length > 0) {
  message += "💼 *Business*\n" + categorized.Business.join('\n') + "\n\n";
}

if (categorized.Personal.length > 0) {
  message += "💬 *Others*\n" + categorized.Personal.join('\n') + "\n";
}

if (emails.length === 0) {
  message = "📩 No new unread emails.";
}

return [{ json: { message, count: emails.length } }];
